//! Bootstrap / node tokens (§4.0 m2m, §4.3, A3 "节点侧 bootstrap token 独立通道").
//!
//! Two layers:
//! - **global bootstrap token** — console-side secret that admits the *first*
//!   self-registration of each unknown node (register only, never again once
//!   the node row exists). Set via `TAILRACE_BOOTSTRAP_TOKEN`, otherwise
//!   generated per process start (printed once by the binary); engine nodes
//!   must then register while the operator can read it.
//! - **per-node token** — freshly generated by the server on every successful
//!   register and echoed in that response exactly once; only its sha256 hex
//!   digest is stored on `node.bootstrap_token` (NULL = revoked), so the
//!   plaintext never resides in the database (audit-console H1). Known nodes
//!   authenticate on register/heartbeat by presenting the plaintext token.

use console_store::Store;

use crate::error::ct_eq;
use crate::token::{generate_token, token_hash, BOOTSTRAP_TOKEN_PREFIX};

pub const BOOTSTRAP_TOKEN_ENV: &str = "TAILRACE_BOOTSTRAP_TOKEN";

#[derive(Clone)]
pub struct BootstrapAuthority {
    global_token: String,
}

impl BootstrapAuthority {
    /// From env when pinned, else freshly generated (caller prints it once).
    pub fn from_env_or_generate() -> (Self, Option<String>) {
        match std::env::var(BOOTSTRAP_TOKEN_ENV) {
            Ok(tok) if !tok.trim().is_empty() => (Self { global_token: tok }, None),
            _ => {
                let tok = generate_token(BOOTSTRAP_TOKEN_PREFIX);
                (
                    Self {
                        global_token: tok.clone(),
                    },
                    Some(tok),
                )
            }
        }
    }

    /// Fixed token (tests).
    pub fn new(global_token: impl Into<String>) -> Self {
        Self {
            global_token: global_token.into(),
        }
    }

    pub fn global_token(&self) -> &str {
        &self.global_token
    }

    fn global_matches(&self, presented: &str) -> bool {
        ct_eq(presented, &self.global_token)
    }

    /// m2m verdict for `POST /api/nodes/register` / `heartbeat`.
    ///
    /// - unknown node_key: only the global bootstrap token admits it (register
    ///   only; heartbeats from unknown nodes are rejected). Once the node row
    ///   exists the global token never works for it again — only the issued
    ///   per-node token does;
    /// - known node: sha256(presented token) must equal the stored digest
    ///   (constant-time; NULL = revoked → 401).
    pub fn verify_node(
        &self,
        store: &Store,
        node_key: Option<&str>,
        presented_token: Option<&str>,
        allow_unknown: bool,
    ) -> Result<Option<String>, VerifyError> {
        let (Some(node_key), Some(token)) = (node_key, presented_token) else {
            return Err(VerifyError::Missing);
        };
        let node = store
            .node_by_key(node_key)
            .map_err(|_| VerifyError::Store)?;
        match node {
            Some(node) => match &node.bootstrap_token {
                // Only the digest is at rest; the plaintext (and the global
                // token) can never match it.
                Some(stored) if ct_eq(&token_hash(token), stored) => Ok(Some(node_key.to_string())),
                _ => Err(VerifyError::BadToken),
            },
            None => {
                if allow_unknown && self.global_matches(token) {
                    Ok(Some(node_key.to_string()))
                } else {
                    Err(VerifyError::BadToken)
                }
            }
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum VerifyError {
    /// No nodeKey/token in the payload.
    Missing,
    /// Unknown or mismatched token (401 per §4.3).
    BadToken,
    /// Store failure.
    Store,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn unknown_node_needs_global_token_only_for_register() {
        let store = Store::open_in_memory().unwrap();
        let auth = BootstrapAuthority::new("tok-secret");
        // register: unknown node + matching global token -> ok
        assert_eq!(
            auth.verify_node(&store, Some("sn-new"), Some("tok-secret"), true)
                .unwrap()
                .as_deref(),
            Some("sn-new")
        );
        // register: unknown node + wrong token -> 401
        assert_eq!(
            auth.verify_node(&store, Some("sn-new"), Some("nope"), true)
                .unwrap_err(),
            VerifyError::BadToken
        );
        // heartbeat: unknown node is never admitted even with the global token
        assert_eq!(
            auth.verify_node(&store, Some("sn-new"), Some("tok-secret"), false)
                .unwrap_err(),
            VerifyError::BadToken
        );
        // missing credentials
        assert_eq!(
            auth.verify_node(&store, None, Some("tok-secret"), true)
                .unwrap_err(),
            VerifyError::Missing
        );
        assert_eq!(
            auth.verify_node(&store, Some("sn-new"), None, true)
                .unwrap_err(),
            VerifyError::Missing
        );
    }

    #[test]
    fn known_node_uses_stored_token_and_revocation() {
        let store = Store::open_in_memory().unwrap();
        // Seed the row the way the register handler does: sha256 at rest.
        store
            .upsert_self_registered("sn-a", None, None, &token_hash("node-tok"))
            .unwrap();
        let auth = BootstrapAuthority::new("tok-secret");
        // plaintext token works (register and heartbeat); the global token and
        // the stored digest itself do NOT
        for allow_unknown in [true, false] {
            assert_eq!(
                auth.verify_node(&store, Some("sn-a"), Some("node-tok"), allow_unknown)
                    .unwrap()
                    .as_deref(),
                Some("sn-a")
            );
            assert_eq!(
                auth.verify_node(&store, Some("sn-a"), Some("tok-secret"), allow_unknown)
                    .unwrap_err(),
                VerifyError::BadToken
            );
            assert_eq!(
                auth.verify_node(
                    &store,
                    Some("sn-a"),
                    Some(&token_hash("node-tok")),
                    allow_unknown
                )
                .unwrap_err(),
                VerifyError::BadToken
            );
        }
        // revoked (NULL) rejects everything
        store.revoke_bootstrap_token("sn-a").unwrap();
        assert_eq!(
            auth.verify_node(&store, Some("sn-a"), Some("node-tok"), true)
                .unwrap_err(),
            VerifyError::BadToken
        );
    }
}
